            [PSCustomObject]@{ Name = 'oldest'; SizeBytes = 100; CreatedAt = (Get-Date '2026-06-10'); WorkflowId = 'deploy' }
        )

        $plan = Get-ArtifactCleanupPlan -Artifact $artifacts -MaxTotalSizeBytes 150 -ReferenceDate (Get-Date '2026-07-01')

