Import-Module powershell-yaml
$yaml = Get-Content /home/passp/repos/GHA-bench-sonnet5/workspaces/2026-06-30_191904/17-artifact-cleanup-script/powershell-sonnet5/.github/workflows/artifact-cleanup-script.yml -Raw | ConvertFrom-Yaml -Ordered
