1	<#
2	    ArtifactCleanup module
3	    Applies retention policies (max age, max total size, keep-latest-N per
4	    workflow) to a list of CI artifacts and produces a deletion plan.
5	#>
6	
7	function ConvertTo-UtcDateTime {
8	    <#
9	        Normalizes a date value to a Kind=Utc [datetime], regardless of
10	        whether it arrives as a raw ISO 8601 string or as a [datetime]
11	        already produced by ConvertFrom-Json (which auto-converts ISO 8601
12	        strings to [datetime] with Kind=Utc, preserving the original
13	        wall-clock digits). Re-stringifying such a value with a plain
14	        [string] cast drops the UTC marker and Parse/ToUniversalTime would
15	        then reinterpret it as local time -- shifting it by the host's UTC
16	        offset. Handling [datetime] inputs directly avoids that round trip.
17	    #>
18	    param(
19	        [Parameter(Mandatory)]
20	        $Value
21	    )
22	
23	    if ($Value -is [datetime]) {
24	        switch ($Value.Kind) {
25	            'Utc' { return $Value }
26	            'Local' { return $Value.ToUniversalTime() }
27	            default { return [datetime]::SpecifyKind($Value, [System.DateTimeKind]::Utc) }
28	        }
29	    }
30	
31	    $styles = [System.Globalization.DateTimeStyles]::AdjustToUniversal -bor [System.Globalization.DateTimeStyles]::AssumeUniversal
32	    $parsed = [datetime]::MinValue
33	    $ok = [datetime]::TryParse([string]$Value, [System.Globalization.CultureInfo]::InvariantCulture, $styles, [ref]$parsed)
34	    if (-not $ok) {
35	        throw "Value '$Value' could not be parsed as a date."
36	    }
37	    return $parsed
38	}
39	
40	function ConvertTo-ArtifactObject {
41	    <#
42	        Normalizes a raw artifact record (PSCustomObject/hashtable, e.g. from
43	        JSON) into a typed artifact object, validating required fields so bad
44	        input fails fast with a meaningful message rather than propagating
45	        nulls through the retention logic.
46	    #>
47	    param(
48	        [Parameter(Mandatory)]
49	        $Raw
50	    )
51	
52	    if (-not $Raw.name) {
53	        throw "Artifact is missing required field 'Name'."
54	    }
55	    if ($null -eq $Raw.sizeBytes -or $Raw.sizeBytes -lt 0) {
56	        throw "Artifact '$($Raw.name)' has an invalid 'SizeBytes' value: must be a non-negative number."
57	    }
58	    if (-not $Raw.workflowId) {
59	        throw "Artifact '$($Raw.name)' is missing required field 'WorkflowId'."
60	    }
61	
62	    try {
63	        $createdAt = ConvertTo-UtcDateTime -Value $Raw.createdAt
64	    } catch {
65	        throw "Artifact '$($Raw.name)' has an invalid 'CreatedAt' value: '$($Raw.createdAt)' could not be parsed as a date."
66	    }
67	
68	    [PSCustomObject]@{
69	        Name       = [string]$Raw.name
70	        SizeBytes  = [long]$Raw.sizeBytes
71	        CreatedAt  = $createdAt
72	        WorkflowId = [string]$Raw.workflowId
73	    }
74	}
75	
76	function Get-ArtifactCleanupPlan {
77	    <#
78	        Pure planning function: given a set of artifacts and retention policy
79	        limits, decides which artifacts to delete and which to retain. Never
80	        mutates or deletes anything itself -- Invoke-ArtifactCleanup performs
81	        the actual (mock) deletion based on this plan, which is what makes
82	        DryRun mode possible without duplicating the decision logic.
83	
84	        Precedence rules (highest to lowest):
85	          1. KeepLatestPerWorkflow protects the N newest artifacts of each
86	             workflow from every other rule.
87	          2. MaxAgeDays deletes any unprotected artifact older than the limit.
88	          3. MaxTotalSizeBytes evicts remaining unprotected artifacts,
89	             oldest-first, until the survivor set fits under the cap.
90	    #>
91	    param(
92	        [Parameter(Mandatory)]
93	        [AllowEmptyCollection()]
94	        [object[]] $Artifact,
95	
96	        [int] $MaxAgeDays = 0,
97	        [long] $MaxTotalSizeBytes = 0,
98	        [int] $KeepLatestPerWorkflow = 0,
99	        [datetime] $ReferenceDate = (Get-Date)
100	    )
101	
102	    if ($MaxAgeDays -lt 0) {
103	        throw "MaxAgeDays must be zero (disabled) or positive, got $MaxAgeDays."
104	    }
105	    if ($MaxTotalSizeBytes -lt 0) {
106	        throw "MaxTotalSizeBytes must be zero (disabled) or positive, got $MaxTotalSizeBytes."
107	    }
108	    if ($KeepLatestPerWorkflow -lt 0) {
109	        throw "KeepLatestPerWorkflow must be zero (disabled) or positive, got $KeepLatestPerWorkflow."
110	    }
111	
112	    # Decision record per artifact: Deleted (bool) + Reason (string), carried
113	    # alongside the original artifact fields so the caller gets full context.
114	    $decisions = foreach ($item in $Artifact) {
115	        [PSCustomObject]@{
116	            Name       = $item.Name
117	            SizeBytes  = [long]$item.SizeBytes
118	            CreatedAt  = $item.CreatedAt
119	            WorkflowId = $item.WorkflowId
120	            Deleted    = $false
121	            Protected  = $false
122	            Reason     = $null
123	        }
124	    }
125	
126	    # Rule 1: keep-latest-N per workflow protects the newest N artifacts of
127	    # each workflow group from age/size eviction.
128	    if ($KeepLatestPerWorkflow -gt 0) {
129	        $groups = $decisions | Group-Object -Property WorkflowId
130	        foreach ($group in $groups) {
131	            $newest = $group.Group | Sort-Object -Property CreatedAt -Descending | Select-Object -First $KeepLatestPerWorkflow
132	            foreach ($item in $newest) {
133	                $item.Protected = $true
134	                $item.Reason = 'kept-latest-N'
135	            }
136	        }
137	    }
138	
139	    # Rule 2: max age deletes unprotected artifacts older than the limit.
140	    if ($MaxAgeDays -gt 0) {
141	        foreach ($item in $decisions) {
142	            if ($item.Protected -or $item.Deleted) { continue }
143	            $ageDays = ($ReferenceDate - $item.CreatedAt).TotalDays
144	            if ($ageDays -gt $MaxAgeDays) {
145	                $item.Deleted = $true
146	                $item.Reason = 'max-age-exceeded'
147	            }
148	        }
149	    }
150	
151	    # Rule 3: max total size evicts remaining unprotected artifacts,
152	    # oldest-first, until the survivor set fits under the cap.
153	    if ($MaxTotalSizeBytes -gt 0) {
154	        $survivors = $decisions | Where-Object { -not $_.Deleted }
155	        $totalSize = ($survivors | Measure-Object -Property SizeBytes -Sum).Sum
156	        if (-not $totalSize) { $totalSize = 0 }
157	
158	        if ($totalSize -gt $MaxTotalSizeBytes) {
159	            $evictionCandidates = $survivors | Where-Object { -not $_.Protected } | Sort-Object -Property CreatedAt
160	            foreach ($item in $evictionCandidates) {
161	                if ($totalSize -le $MaxTotalSizeBytes) { break }
162	                $item.Deleted = $true
163	                $item.Reason = 'max-total-size-exceeded'
164	                $totalSize -= $item.SizeBytes
165	            }
166	        }
167	    }
168	
169	    foreach ($item in $decisions) {
170	        if (-not $item.Deleted -and -not $item.Reason) {
171	            $item.Reason = 'within-policy'
172	        }
173	    }
174	
175	    $toDelete = @($decisions | Where-Object Deleted)
176	    $toRetain = @($decisions | Where-Object { -not $_.Deleted })
177	    $bytesReclaimed = ($toDelete | Measure-Object -Property SizeBytes -Sum).Sum
178	    if (-not $bytesReclaimed) { $bytesReclaimed = 0 }
179	    $retainedBytes = ($toRetain | Measure-Object -Property SizeBytes -Sum).Sum
180	    if (-not $retainedBytes) { $retainedBytes = 0 }
181	
182	    [PSCustomObject]@{
183	        ToDelete = $toDelete
184	        ToRetain = $toRetain
185	        Summary  = [PSCustomObject]@{
186	            TotalArtifacts = $decisions.Count
187	            DeletedCount   = $toDelete.Count
188	            RetainedCount  = $toRetain.Count
189	            BytesReclaimed = [long]$bytesReclaimed
190	            RetainedBytes  = [long]$retainedBytes
191	        }
192	    }
193	}
194	
195	function Remove-Artifact {
196	    <#
197	        Performs the actual (mock) deletion of a single artifact. In a real
198	        pipeline this would call the GitHub Artifacts REST API
199	        (DELETE /repos/{owner}/{repo}/actions/artifacts/{artifact_id}); here
200	        it is a seam that Pester can -Mock to verify Invoke-ArtifactCleanup
201	        calls it the right number of times without hitting a network.
202	    #>
203	    param(
204	        [Parameter(Mandatory)]
205	        $Artifact
206	    )
207	
208	    [PSCustomObject]@{
209	        Name      = $Artifact.Name
210	        Deleted   = $true
211	        Timestamp = (Get-Date).ToString('o')
212	    }
213	}
214	
215	function Invoke-ArtifactCleanup {
216	    <#
217	        Orchestrates a cleanup run: computes the retention plan via
218	        Get-ArtifactCleanupPlan, then executes it by calling Remove-Artifact
219	        for every artifact marked for deletion -- unless -DryRun is set, in
220	        which case the plan is still computed and returned (so callers can
221	        see exactly what *would* happen) but no removal calls are made.
222	    #>
223	    param(
224	        [Parameter(Mandatory)]
225	        [AllowEmptyCollection()]
226	        [object[]] $Artifact,
227	
228	        [int] $MaxAgeDays = 0,
229	        [long] $MaxTotalSizeBytes = 0,
230	        [int] $KeepLatestPerWorkflow = 0,
231	        [datetime] $ReferenceDate = (Get-Date),
232	        [switch] $DryRun
233	    )
234	
235	    $plan = Get-ArtifactCleanupPlan -Artifact $Artifact -MaxAgeDays $MaxAgeDays `
236	        -MaxTotalSizeBytes $MaxTotalSizeBytes -KeepLatestPerWorkflow $KeepLatestPerWorkflow `
237	        -ReferenceDate $ReferenceDate
238	
239	    $removed = 0
240	    if (-not $DryRun) {
241	        foreach ($item in $plan.ToDelete) {
242	            $null = Remove-Artifact -Artifact $item
243	            $removed++
244	        }
245	    }
246	
247	    [PSCustomObject]@{
248	        Plan                     = $plan
249	        DryRun                   = [bool]$DryRun
250	        ArtifactsActuallyRemoved = $removed
251	    }
252	}
253	
254	Export-ModuleMember -Function ConvertTo-UtcDateTime, ConvertTo-ArtifactObject, Get-ArtifactCleanupPlan, Remove-Artifact, Invoke-ArtifactCleanup
255
